package talive_test

import (
	"reflect"
	"testing"

	"github.com/MoroZvlg/talive"
)

// NOTE: The CSV fixtures consumed by these tests (test_data/zigzag/output_*.csv) were generated by
// streaming input_data2.csv through python talipp.ZigZag and reshaping its sparse-pivot output \
// into the per-bar 3-slot layout. See scripts/zigzag_oracle.py.

func TestZigZagDefault(t *testing.T) {
	candles, _ := readCandles("test_data/input_data2.csv")
	expected, _ := readData("test_data/zigzag/output_default.csv", []int{1, 2, 3}, 7)
	indicator, _ := talive.NewZigZag(0.05, 5)
	got := [][]float64{
		make([]float64, len(candles)),
		make([]float64, len(candles)),
		make([]float64, len(candles)),
	}
	for i, candle := range candles {
		res := indicator.Next(candle)
		got[0][i] = roundFloat(res[0], 7)
		got[1][i] = roundFloat(res[1], 7)
		got[2][i] = roundFloat(res[2], 7)
	}
	if !reflect.DeepEqual(got[0], expected[0]) {
		t.Fatal(`[ZigZag(0.05,5)] LastHigh values didn't match `, difference(got[0], expected[0]))
	}
	if !reflect.DeepEqual(got[1], expected[1]) {
		t.Fatal(`[ZigZag(0.05,5)] LastLow values didn't match `, difference(got[1], expected[1]))
	}
	if !reflect.DeepEqual(got[2], expected[2]) {
		t.Fatal(`[ZigZag(0.05,5)] Event values didn't match `, difference(got[2], expected[2]))
	}
}

